```js
export function moveBody(body, dx, dy, level, opts={}) {
  const {oneWay=true, dropTimer=0} = opts;
  const res = {hitX:false, hitY:false, onGround:false};
  if (dx !== 0) {
    body.x += dx;
    const y0 = Math.floor(body.y / TILE), y1 = Math.floor((body.y + body.h - 0.01) / TILE);
    if (dx > 0) {
      const x1 = Math.floor((body.x + body.w - 0.01) / TILE);
      for (let ty=y0; ty<=y1; ty++) if (level.isSolid(x1,ty)) { body.x = Math.min(body.x, x1*TILE - body.w); res.hitX = true; }
    } else {
      const x0 = Math.floor(body.x / TILE);
      for (let ty=y0; ty<=y1; ty++) if (level.isSolid(x0,ty)) { body.x = Math.max(body.x, (x0+1)*TILE); res.hitX = true; }
    }
  }
  if (dy !== 0) {
    const prevBottom = body.y + body.h;
    body.y += dy;
    const x0 = Math.floor((body.x + 1) / TILE), x1 = Math.floor((body.x + body.w - 1) / TILE);
    if (dy > 0) {
      const y1 = Math.floor((body.y + body.h - 0.01) / TILE);
      for (let tx=x0; tx<=x1; tx++) {
        const solid = level.isSolid(tx,y1);
        const platform = oneWay && level.isOneWay(tx,y1) && prevBottom <= y1*TILE + 1 && dropTimer<=0;
        if (solid || platform) { body.y = Math.min(body.y, y1*TILE - body.h); res.onGround = true; }
      }
      // also check the tile just below feet when exactly aligned? prevBottom <= top+1 handles.
