123:       last = now;
124:       acc += dt;
125:       let guard = 0;
126:       while (acc >= STEP && guard < 5) {
127:         this.step(STEP);
128:         acc -= STEP;
129:         guard++;
130:       }
131:       this.renderer.draw(this, dt);
132:       requestAnimationFrame(frame);
133:     };
