360:   step(dt) {
361:     this.time += dt;
362:     this.shake = Math.max(0, this.shake - dt * 42);
363:     this.flashHurt = Math.max(0, this.flashHurt - dt);
364: 
365:     if (this.state === 'title') {
366:       this.updateTitle(dt);
367:       this.input.clearFrame();
368:       return;
369:     }
370: 
371:     if (this.state === 'dead') {
372:       this.deathTimer -= dt;
373:       this.updateParticles(dt);
374:       this.shake = Math.max(0, this.shake - dt * 10);
375:       if (this.deathTimer <= 0) this.respawnPlayer();
376:       this.input.clearFrame();
377:       this.applyChrome();
378:       return;
379:     }
380: 
381:     if (this.state === 'paused' || this.state === 'shop' || this.state === 'clear' || this.state === 'victory') {
382:       if (this.input.pressed('pause')) {
383:         if (this.state === 'paused') this.resumeGame();
384:         else if (this.state === 'shop') this.closeShop();
385:         else if (this.state === 'clear') this.nextFromClear();
386:       }
387:       this.input.clearFrame();
388:       this.applyChrome();
389:       return;
390:     }
391: 
392:     if (this.input.pressed('pause')) {
393:       this.pauseGame();
394:       this.input.clearFrame();
395:       this.applyChrome();
396:       return;
397:     }
398: 
399:     if (this.hitstop > 0) {
400:       this.hitstop -= dt;
401:       this.input.clearFrame();
402:       return;
403:     }
404: 
405:     this.runTime += dt;
406: 
407:     this.player.update(dt, this);
408:     if (this.state !== 'playing') {
409:       this.input.clearFrame();
410:       this.applyChrome();
411:       return;
412:     }
413: 
414:     for (const enemy of this.enemies) {
415:       if (!enemy.dead) enemy.update(dt, this);
416:     }
417:     this.enemies = this.enemies.filter((e) => !e.dead);
418: 
419:     if (this.boss) {
420:       this.boss.update(dt, this);
421:       if (this.boss.dying && this.boss.deathT > 1.8) this.boss = null;
422:     }
423: 
424:     for (const projectile of this.projectiles) projectile.update(dt, this);
425:     this.projectiles = this.projectiles.filter((p) => !p.dead);
426: 
427:     for (const pickup of this.pickups) pickup.update(dt, this);
428:     this.pickups = this.pickups.filter((p) => !p.dead);
429: 
430:     this.handleContacts();
431:     this.checkBossTrigger();
432:     this.checkCheckpoints();
433:     this.updateInteraction();
434:     this.updateArenaBounds();
435: 
436:     this.updateParticles(dt);
437:     this.updateTexts(dt);
438:     this.updateCamera(dt);
439:     this.updateBossBar();
440:     this.applyChrome();
441:     this.input.clearFrame();
442:   }
443: 
444:   updateTitle(dt) {
445:     const lvl = this.level;
446:     const targetX =
447:       this.level.spawn.x - this.viewW * 0.36 + Math.sin(this.time * 0.09) * this.viewW * 0.07;
448:     const targetY = lvl.arenaData.groundY - this.viewH * 0.66;
449:     const bounds = this.titleBounds || { x0: 0, x1: lvl.widthPx, y0: 0, y1: lvl.heightPx };
450:     const maxX = Math.max(bounds.x0, bounds.x1 - this.viewW);
451:     const targetXClamped = clamp(targetX, bounds.x0, maxX);
452:     this.camera.x = damp(this.camera.x, targetXClamped, 1.5, dt);
453:     this.camera.y = damp(this.camera.y, targetY, 1.5, dt);
454:     this.updateParticles(dt);
455:     this.updateTexts(dt);
456:   }
457: 
458:   updateParticles(dt) {
459:     updateParticles(this, dt);
460:   }
