462:   updateTexts(dt) {
463:     for (let i = this.texts.length - 1; i >= 0; i--) {
464:       const t = this.texts[i];
465:       t.life -= dt;
466:       t.y -= 38 * dt;
467:       if (t.life <= 0) this.texts.splice(i, 1);
468:     }
469:   }
