475:   handleContacts() {
476:     const p = this.player;
477:     for (const e of this.enemies) {
478:       if (e.dead || !overlap(p, e)) continue;
479:       const stomp = p.vy > 70 && p.prevY + p.h <= e.y + 16 && e.type !== 'spitter';
480:       if (stomp) {
481:         e.hurt(2, sign(e.cx - p.cx) || 1, this);
482:         p.vy = -470;
483:         p.onGround = false;
484:         p.airJumps = p.armorTier >= 3 ? 1 : p.airJumps;
485:         this.audio.stomp();
486:         this.shake = Math.max(this.shake, 5);
487:         this.hitstop = Math.max(this.hitstop, 0.03);
488:       } else {
489:         p.hurt(1, e.cx, this);
490:       }
491:     }
492: 
493:     if (this.boss && !this.boss.dying && this.boss.contactDamage() > 0 && overlap(p, this.boss)) {
494:       p.hurt(this.boss.contactDamage(), this.boss.cx, this);
495:     }
496:   }
497: 
498:   playerStrike(hb, player) {
499:     const dmg = 2 + (player.armorTier >= 3 ? 1 : 0);
500:     for (const e of this.enemies) {
501:       if (e.dead || player.hitSet.has(e) || !overlap(hb, e)) continue;
502:       player.hitSet.add(e);
503:       e.hurt(dmg, player.facing, this);
504:       this.hitstop = Math.max(this.hitstop, 0.035);
505:       this.shake = Math.max(this.shake, 5);
506:     }
507: 
508:     if (this.boss && !this.boss.dying && this.boss.intro <= 0 && !player.hitSet.has(this.boss) && overlap(hb, this.boss)) {
509:       player.hitSet.add(this.boss);
510:       this.boss.hit(dmg, this);
511:       this.hitstop = Math.max(this.hitstop, 0.045);
512:       this.shake = Math.max(this.shake, 7);
513:     }
514: 
515:     for (const projectile of this.projectiles) {
516:       if (projectile.dead || player.hitSet.has(projectile)) continue;
517:       if (overlap(hb, { x: projectile.x - projectile.r, y: projectile.y - projectile.r, w: projectile.r * 2, h: projectile.r * 2 })) {
518:         player.hitSet.add(projectile);
519:         projectile.burst(this);
520:         this.audio.hit();
521:       }
522:     }
523:   }
