568:   checkBossTrigger() {
569:     if (this.bossActive || this.bossDead) return;
570:     const arena = this.level.arenaData;
571:     if (this.player.cx > arena.triggerX) {
572:       this.boss = new Boss(this.level.boss, arena, this);
573:       this.bossActive = true;
574:       this.cameraBounds = {
575:         x0: arena.x0 - 40,
576:         x1: arena.x1 + 40,
577:         y0: arena.groundY - 740,
578:         y1: arena.groundY + 60
579:       };
580:       this.showBossBar();
581:       this.audio.startMusic('boss');
582:       this.shake = Math.max(this.shake, 12);
583:       this.toast(`${this.level.bossName} awakens`);
584:       this.player.invuln = Math.max(this.player.invuln, 0.8);
