588:   updateArenaBounds() {
589:     if (!this.bossActive) return;
590:     const a = this.level.arenaData;
591:     const p = this.player;
592:     if (p.x < a.x0 + 12) {
593:       p.x = a.x0 + 12;
594:       p.vx = Math.max(0, p.vx);
595:     }
596:     if (p.x + p.w > a.x1 - 12) {
597:       p.x = a.x1 - p.w - 12;
598:       p.vx = Math.min(0, p.vx);
599:     }
600:   }
