602:   checkCheckpoints() {
603:     const p = this.player;
604:     for (const c of this.level.checkpoints) {
605:       if (c.active) continue;
606:       if (Math.hypot(p.cx - c.x, p.cy - c.y) < 74) {
607:         c.active = true;
608:         this.checkpoint = { x: c.x, y: c.y };
609:         p.hp = p.maxHp;
610:         this.audio.checkpoint();
611:         this.toast('Checkpoint lit — the spores remember');
612:         this.addText(c.x, c.y - 70, 'Checkpoint', '#8ff7df');
613:         this.shake = Math.max(this.shake, 3);
614:         this.saveProgress();
615:         this.updateHUD();
616:         for (let i = 0; i < 14; i++) {
617:           this.particles.push({
618:             x: c.x,
619:             y: c.y - 36,
620:             vx: (Math.random() - 0.5) * 120,
621:             vy: -40 - Math.random() * 120,
622:             life: 0.8,
