482:     const p = game.player;
483:     if (p && overlap({ x: this.x - this.r, y: this.y - this.r, w: this.r * 2, h: this.r * 2 }, p)) {
484:       p.hurt(1, this.x, game);
485:       this.burst(game);
486:       return;
