498:       screech: ['#ff86c8', '#ffd3ef'],
499:       rock: ['#a99578', '#e0cba4']
500:     };
501:     const [a, b] = colors[this.type] || colors.goo;
502:     burst(game, this.x, this.y, {
503:       count: 8,
504:       color: a,
505:       color2: b,
506:       speed: 150,
507:       life: 0.4,
508:       gravity: 500,
