515: export class Pickup {
516:   constructor(def) {
517:     this.type = def.type;
518:     this.value = def.value || 1;
519:     this.big = !!def.big;
520:     this.x = def.x;
521:     this.y = def.y;
522:     this.baseY = def.y;
523:     this.t = Math.random() * 8;
524:     this.seed = Math.random() * 6;
525:     this.dead = false;
526:     this.r = this.big ? 16 : 11;
527:   }
