540:     if (d < 105) {
541:       const pull = 420 * (1 - d / 130);
542:       this.x += (dx / d) * pull * dt;
543:       this.y += (dy / d) * pull * dt;
544:       this.baseY = this.y;
545:     }
546:     if (d < 27) {
547:       this.dead = true;
548:       game.collectPickup(this);
549:     }
550:   }
551: }
