import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);
await page.click('#playBtn');
await page.waitForTimeout(600);

await page.evaluate(() => {
  const g = window.game;
  window.__log = [];
  window.__last = { lvl: g.levelIndex, maxX: 0, t: 0 };
  const key = (a, down) => g.input.setVirtual(a, down);
  let jumpLatch = 0;
  window.__bot = setInterval(() => {
    if (!g.player) return;
    if (g.state === 'clear') {
      document.getElementById('clearNext').click();
      return;
    }
    if (g.state === 'victory') { key('right', false); return; }
    if (g.state === 'dead') return;
    if (g.state === 'shop') {
      const btn = document.querySelector('[data-buy]:not([disabled])');
      if (btn) btn.click();
      else document.getElementById('shopClose').click();
      return;
    }
    if (g.state !== 'playing') return;
    const p = g.player;
    const lvl = g.level;
    if (g.levelIndex !== window.__last.lvl) {
      window.__last = { lvl: g.levelIndex, maxX: p.x, t: 0 };
    }
    window.__last.maxX = Math.max(window.__last.maxX, p.x);
    key('right', true);
    const feetY = p.y + p.h + 4;
    const ahead = Math.floor((p.x + p.w + 16) / 48);
    const footRow = Math.floor(feetY / 48);
    const chestRow = Math.floor((p.y + p.h * 0.5) / 48);
    let gap = true;
    for (let ty = footRow; ty <= footRow + 3; ty++) {
      if (lvl.isSolid(ahead, ty) || lvl.isOneWay(ahead, ty)) { gap = false; break; }
    }
    let wall = lvl.isSolid(ahead, chestRow) || lvl.isSolid(ahead, footRow - 1);
    let hazard = false;
    for (let tx = ahead; tx <= ahead + 2; tx++) {
      for (let ty = footRow - 1; ty <= footRow; ty++) if (lvl.isHazard(tx, ty)) hazard = true;
    }
    let enemyNear = false;
    for (const e of g.enemies) if (!e.dead && Math.abs(e.cx - p.cx) < 120 && Math.abs(e.cy - p.cy) < 90) enemyNear = true;
    const bossNear = g.boss && !g.boss.dying && Math.abs(g.boss.cx - p.cx) < 160;
    const wantJump = (gap && p.onGround) || wall || hazard || (enemyNear && p.onGround) || (bossNear && p.onGround) || (p.onGround && Math.abs(p.vx) < 20);
    const now = performance.now();
    if (wantJump && now - jumpLatch > 180) {
      jumpLatch = now;
      key('jump', false);
      setTimeout(() => key('jump', true), 15);
      setTimeout(() => key('jump', false), 260);
    }
    if (enemyNear || bossNear) {
      key('attack', false);
      setTimeout(() => key('attack', true), 10);
      setTimeout(() => key('attack', false), 80);
    }
    if (g.nearDoor && g.bossDead) {
      key('interact', false);
      setTimeout(() => key('interact', true), 10);
      setTimeout(() => key('interact', false), 80);
    }
  }, 50);
});

