drawForegroundFlora() {
  const ctx = this.ctx;
  const theme = this.theme;
  const layers = [
    { spacing: 210, p: 1.06, scale: 0.72, alpha: 0.45, color: theme.near },
    { spacing: 300, p: 1.2, scale: 1, alpha: 0.72, color: theme.groundDark }
  ];
  const baseY = this.vh + 5;

  layers.forEach((L, li) => {
    const color = rgba(L.color, L.alpha);
    this.layer(L.spacing, L.p, (x, i) => {
      const seed = i * 13.7 + li * 31.1;
      const pick = hash(seed);
      const h = (28 + hash(seed + 4.2) * 56) * L.scale;
      ctx.save();
      if (pick < 0.4) {
        // grass tuft
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.8;
        ctx.lineCap = 'round';
        for (let b = 0; b < 7; b++) {
          const bx = x + (hash(seed + b * 3.1) - 0.5) * 30;
          const bh = h * (0.45 + hash(seed + b * 5.7) * 0.7);
          const lean = (hash(seed + b * 7.3) - 0.5) * 18;
          ctx.beginPath();
          ctx.moveTo(bx, baseY);
          ctx.quadraticCurveTo(bx + lean * 0.3, baseY - bh * 0.6, bx + lean, baseY - bh);
          ctx.stroke();
        }
      } else if (pick < 0.68) {
        // fern
        const sway = (hash(seed + 8.1) - 0.5) * 20;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, baseY);
        ctx.quadraticCurveTo(x + sway * 0.3, baseY - h * 0.55, x + sway, baseY - h);
        ctx.stroke();
        ctx.fillStyle = color;
        for (let f = 0; f < 5; f++) {
          const t = 0.24 + f * 0.14;
          const px = x + sway * t;
          const py = baseY - h * t;
          const len = h * 0.26 * (1 - t * 0.45) * (0.75 + hash(seed + f) * 0.5);
          for (const side of [-1, 1]) {
            ctx.beginPath();
            ctx.moveTo(px, py);
            ctx.quadraticCurveTo(px + side * len * 0.7, py - len * 0.32, px + side * len, py - len * 0.55);
            ctx.quadraticCurveTo(px + side * len * 0.5, py + len * 0.05, px, py);
            ctx.closePath();
            ctx.fill();
          }
        }
      } else if (pick < 0.87) {
        // mushroom silhouette
        const stemW = 4 + h * 0.05;
        ctx.fillStyle = color;
        ctx.fillRect(x - stemW / 2, baseY - h * 0.62, stemW, h * 0.62);
        ellipse(ctx, x, baseY - h * 0.64, h * 0.38, h * 0.2);
        ctx.fill();
        ctx.strokeStyle = rgba(theme.accent, 0.18);
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.ellipse(x, baseY - h * 0.64, h * 0.36, h * 0.18, 0, Math.PI, Math.PI * 2);
        ctx.stroke();
      } else {
        // mossy rock
        ctx.fillStyle = color;
        ellipse(ctx, x, baseY - h * 0.22, h * 0.44, h * 0.3);
        ctx.fill();
        ctx.fillStyle = rgba(theme.cap, 0.16);
        ellipse(ctx, x - h * 0.08, baseY - h * 0.34, h * 0.24, h * 0.1);
