  // soft foreground spore lights
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 5; i++) {
    const x = (hash(i * 9.1 + 4.4) * this.vw + this.t * (4 + i * 2) + this.cam.x * 0.05) % this.vw;
    const y = this.vh * (0.74 + hash(i * 5.3) * 0.2) + Math.sin(this.t * 0.7 + i) * 8;
