input.content:
import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const errors = [];
async function newPage(viewport, isMobile = false) {
  const context = await browser.newContext({ viewport, isMobile, hasTouch: isMobile, deviceScaleFactor: 1 });
  const page = await context.newPage();
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  return page;
}

const page = await newPage({ width: 1440, height: 900 });
await page.screenshot({ path: '/tmp/opencode/shots/new-title.png' });

await page.click('#playBtn');
await page.waitForTimeout(3600);
await page.screenshot({ path: '/tmp/opencode/shots/new-start.png' });

await page.evaluate(() => {
  const g = window.game;
  g.player.x = 38 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.player.facing = 1;
  g.snapCamera();
});
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/shots/new-mid.png' });

await page.evaluate(() => {
  const g = window.game;
  g.spores = 30;
  g.updateHUD();
  const f = g.level.forges[0];
  g.player.x = f.x - g.player.w / 2;
  g.player.y = f.y - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(300);
await page.keyboard.press('e');
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/shots/new-shop.png' });
const buy = await page.$('[data-buy="1"]:not([disabled])');
if (buy) await buy.click();
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shots/new-shop-bought.png' });
await page.click('#shopClose');

await page.evaluate(() => {
  const g = window.game;
  g.player.x = 95 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(2200);
await page.screenshot({ path: '/tmp/opencode/shots/new-boss.png' });

const mob = await newPage({ width: 390, height: 844 }, true);
await mob.screenshot({ path: '/tmp/opencode/shots/new-portrait-title.png' });
await mob.click('#playBtn');
await mob.waitForTimeout(3600);
await mob.screenshot({ path: '/tmp/opencode/shots/new-portrait-play.png' });

console.log('errors', errors);

await browser.close();

