import { LEVEL_DEFS, buildLevel } from '/home/runner/work/PlayGround/PlayGround/src/levels.js';

for (let li = 0; li < LEVEL_DEFS.length; li++) {
  const level = buildLevel(li);
  const W = level.width;
  const H = level.height;
  const stand = new Set();
  const key = (x, y) => `${x},${y}`;

  for (let ty = 0; ty < H; ty++) {
    for (let tx = 0; tx < W; tx++) {
      if (level.charAt(tx, ty) !== '.') continue;
      const below = level.charAt(tx, ty + 1);
      if (below === '#' || below === '=') {
        const above = level.charAt(tx, ty - 1);
        const above2 = level.charAt(tx, ty - 2);
        if (above !== '#' && above2 !== '#' && above !== '^') stand.add(key(tx, ty));
      }
    }
  }

  // BFS across walkable surfaces and ballistic jumps.
  const start = `${Math.floor(level.spawn.x / 48)},${Math.floor(level.spawn.y / 48) - 1}`;
  const seen = new Set();
  const queue = [start];
  seen.add(start);
  while (queue.length) {
    const [sx, sy] = queue.pop().split(',').map(Number);
    const candidates = [];
    for (const dx of [-1, 1]) candidates.push([sx + dx, sy]);
    for (let dx = -4; dx <= 4; dx++) {
      for (let up = 0; up <= 3; up++) {
        const dy = -up;
        candidates.push([sx + dx, sy + dy]);
      }
      for (let down = 1; down <= 12; down++) candidates.push([sx + dx, sy + down]);
    }
    for (const [nx, ny] of candidates) {
      const k = key(nx, ny);
      if (!stand.has(k) || seen.has(k)) continue;
      const dx = Math.abs(nx - sx);
      const rise = sy - ny; // positive means target is higher
      if (rise > 2.05) continue;
      if (rise > 0.5 && dx > 3.2) continue;
      if (rise <= 0.5 && dx > 3.9) continue;
      // Require a clear-ish head corridor for upward jumps.
      if (rise > 0) {
        let blocked = false;
        for (let cy = sy - 1; cy >= ny; cy--) {
          for (let cx = Math.min(sx, nx); cx <= Math.max(sx, nx); cx++) {
            if (level.charAt(cx, cy) === '#') blocked = true;
          }
        }
        if (blocked) continue;
      }
      seen.add(k);
      queue.push(k);
    }
  }

  const surfInfo = [...stand].map((k) => k.split(',').map(Number));
  function reachableNear(x, y, radius = 2) {
    const tx = Math.floor(x / 48);
    const ty = Math.floor(y / 48);
    return surfInfo.some(([sx, sy]) => seen.has(key(sx, sy)) && Math.abs(sx - tx) <= radius && Math.abs(sy - ty) <= radius + 2);
  }

  const unreachable = [];
  for (const p of level.pickups) {
    if (!reachableNear(p.x, p.y, 3)) unreachable.push(`pickup @${(p.x / 48).toFixed(1)},${(p.y / 48).toFixed(1)}`);
  }
  for (const e of level.enemies) {
    if (e.type !== 'bat' && !reachableNear(e.x, e.y, 2)) unreachable.push(`${e.type} @${(e.x / 48).toFixed(1)},${(e.y / 48).toFixed(1)}`);
  }
  for (const c of level.checkpoints) if (!reachableNear(c.x, c.y, 2)) unreachable.push(`checkpoint @${(c.x / 48).toFixed(1)}`);
  for (const f of level.forges) if (!reachableNear(f.x, f.y, 2)) unreachable.push(`forge @${(f.x / 48).toFixed(1)}`);
  if (level.door && !reachableNear(level.door.x, level.door.y, 2)) unreachable.push(`door @${(level.door.x / 48).toFixed(1)}`);
  const bossReach = reachableNear(level.arenaData.triggerX + 60, level.arenaData.groundY + 20, 3);

  console.log(`\n[${level.name}] stand cells=${stand.size} reachable=${seen.size} bossArena=${bossReach}`);
  if (unreachable.length) console.log('  UNREACHABLE:', unreachable);

  // pickup inside solid?
  const embedded = level.pickups.filter((p) => level.charAt(Math.floor(p.x / 48), Math.floor(p.y / 48)) === '#');
  console.log('  embedded pickups:', embedded.length);

  // report gaps/step-ups
  const tops = [];
  for (let tx = 0; tx < W; tx++) {
    let top = null;
    for (let ty = 0; ty < H; ty++) if (level.charAt(tx, ty) === '#') { top = ty; break; }
    tops.push(top);
  }
  const transitions = [];
  for (let tx = 1; tx < W; tx++) {
    if (tops[tx] !== tops[tx - 1]) transitions.push(`${tx}:${tops[tx - 1]}->${tops[tx]}`);
  }
  console.log('  top transitions:', transitions.join(' '));
}

