import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
await page.click('#playBtn');
await page.waitForTimeout(400);

async function testLevel(idx) {
  await page.evaluate((i) => {
    const g = window.game;
    clearInterval(window.__bot);
    g.loadLevel(i);
    g.state = 'playing';
    g.player.x = g.level.spawn.x - g.player.w / 2;
    g.player.y = g.level.spawn.y - g.player.h;
    g.snapCamera();
    g.showLevelCard();
    window.__last = { maxX: 0, stuckT: 0 };
    let jumpUntil = 0;
    let nextJump = 0;
    const key = (a, d) => g.input.setVirtual(a, d);
    window.__bot = setInterval(() => {
      if (!g.player) return;
      if (g.state === 'dead') { key('right', false); return; }
      if (g.state !== 'playing') return;
      const p = g.player;
      const lvl = g.level;
      // keep the traversal test alive
      p.hp = p.maxHp;
      p.invuln = Math.max(p.invuln, 0.5);
      p.x = Math.max(p.x, window.__last.maxX - 60);
      window.__last.maxX = Math.max(window.__last.maxX, p.x);
      key('right', true);
      const ahead = Math.floor((p.x + p.w + 18) / 48);
      const footRow = Math.floor((p.y + p.h + 3) / 48);
      let gap = true;
      for (let ty = footRow; ty <= footRow + 3; ty++) {
        if (lvl.isSolid(ahead, ty) || lvl.isOneWay(ahead, ty)) { gap = false; break; }
      }
      let wall = lvl.isSolid(ahead, Math.floor((p.y + p.h * 0.5) / 48)) ||
        lvl.isSolid(ahead, footRow - 1);
      let hazard = false;
      for (let tx = ahead; tx <= ahead + 2; tx++) {
        for (let ty = footRow - 1; ty <= footRow; ty++) if (lvl.isHazard(tx, ty)) hazard = true;
      }
      const now = performance.now();
      if (p.onGround && (gap || wall || hazard) && now > nextJump) {
        nextJump = now + 260;
        jumpUntil = now + 230;
      }
      if (now < jumpUntil) key('jump', true);
      else key('jump', false);
      if (p.onGround && Math.abs(p.vx) < 12) {
        window.__last.stuckT += 50;
      } else window.__last.stuckT = 0;
    }, 50);
  }, idx);

  let best = 0;
  let stall = 0;
  let bossAt = null;
  for (let i = 0; i < 140; i++) {
    await page.waitForTimeout(250);
    const s = await page.evaluate(() => ({
      x: game.player ? game.player.x / 48 : 0,
      state: game.state,
      boss: game.bossActive,
      hp: game.player?.hp,
      deaths: game.deaths
    }));
    if (s.x > best + 0.1) { best = s.x; stall = 0; } else stall++;
    if (s.boss && bossAt === null) bossAt = best;
    if (bossAt !== null && best > (idx === 0 ? 96 : idx === 1 ? 98 : 96)) break;
    if (stall > 30) break;
  }
  const bossX = idx === 0 ? 91.5 : idx === 1 ? 93.5 : 91.5;
  console.log(`level ${idx}: max ${best.toFixed(1)} tiles (boss trigger ${bossX}) boss=${bossAt !== null} deaths=${await page.evaluate(() => game.deaths)}`);
}

for (let i = 0; i < 3; i++) await testLevel(i);
await page.evaluate(() => clearInterval(window.__bot));
await browser.close();

