import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
await page.click('#playBtn');
await page.waitForTimeout(500);

async function fight(idx) {
  await page.evaluate((i) => {
    const g = window.game;
    clearInterval(window.__bot);
    g.loadLevel(i);
    g.state = 'playing';
    g.armor = 3;
    g.spores = 0;
    g.player.setArmorTier(3, true);
    g.player.x = g.level.arenaData.triggerX + 100;
    g.player.y = g.level.arenaData.groundY - g.player.h;
    g.snapCamera();
    g.updateHUD();
    g.enemies.forEach((e) => (e.dead = true));
    g.enemies = [];
    let lastAtk = 0;
    const key = (a, d) => g.input.setVirtual(a, d);
    window.__hits = 0;
    window.__bot = setInterval(() => {
      const p = g.player;
      if (!p || g.state !== 'playing') return;
      p.invuln = 2;
      p.hp = p.maxHp;
      if (!g.boss || g.boss.dying) { key('left', false); key('right', false); return; }
      const b = g.boss;
      const dx = b.cx - p.cx;
      p.facing = Math.sign(dx) || 1;
      key('left', dx < -95);
      key('right', dx > 95);
      const now = performance.now();
      if (Math.abs(dx) < 145 && now - lastAtk > 330) {
        lastAtk = now;
        key('attack', false);
        setTimeout(() => key('attack', true), 10);
        setTimeout(() => key('attack', false), 70);
      }
    }, 40);
  }, idx);

  let lastHp = -1;
  let t = 0;
  for (let i = 0; i < 180; i++) {
    await page.waitForTimeout(200);
    t += 0.2;
    const s = await page.evaluate(() => ({
      hp: game.boss?.hp ?? null,
      dying: game.boss?.dying ?? null,
      dead: game.bossDead,
      state: game.state,
      x: +(game.player.x / 48).toFixed(1),
      atDoor: game.nearDoor
    }));
    if (s.hp !== lastHp) {
      console.log(`  boss${idx} t=${t.toFixed(1)} hp=${s.hp === null ? '-' : Math.round(s.hp)} dead=${s.dead}`);
      lastHp = s.hp;
    }
    if (s.dead) break;
    if (s.state === 'dead') { console.log('  player died'); break; }
  }
  const after = await page.evaluate(() => ({ dead: game.bossDead, state: game.state, boss: game.boss?.dying }));
  console.log('  result', after);
  if (after.dead) {
    await page.evaluate(() => {
      const g = window.game;
      clearInterval(window.__bot);
      g.player.x = g.level.door.x - g.player.w / 2;
      g.player.y = g.level.door.y - g.player.h;
      g.snapCamera();
    });
    await page.waitForTimeout(300);
    await page.keyboard.press('e');
    await page.waitForTimeout(500);
    console.log('  end state', await page.evaluate(() => game.state));
    if ((await page.evaluate(() => game.state)) === 'clear') {
      await page.click('#clearNext');
      await page.waitForTimeout(700);
      console.log('  next level', await page.evaluate(() => ({ lvl: game.levelIndex, state: game.state })));
    }
  }
}

for (let i = 0; i < 3; i++) await fight(i);
console.log('errors', errors);
await browser.close();

