import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const errors = [];
const OUT = '/tmp/opencode/shots';

async function newPage(viewport, isMobile = false) {
  const context = await browser.newContext({ viewport, isMobile, hasTouch: isMobile, deviceScaleFactor: 1 });
  const page = await context.newPage();
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  return page;
}

async function teleport(page, tx, groundY) {
  await page.evaluate(({ tx, groundY }) => {
    const g = window.game;
    g.player.x = tx * 48 - g.player.w / 2;
    g.player.y = (groundY ?? g.level.arenaData.groundY) - g.player.h;
    g.player.vx = 0; g.player.vy = 0;
    g.player.facing = 1;
    g.snapCamera();
  }, { tx, groundY });
}

// ---------- Desktop 1440x900 ----------
const page = await newPage({ width: 1440, height: 900 });
await page.screenshot({ path: `${OUT}/final-title.png` });

await page.click('#playBtn');
await page.waitForTimeout(3400);
await page.screenshot({ path: `${OUT}/final-play.png` });

// mid level
await teleport(page, 38);
await page.waitForTimeout(700);
await page.screenshot({ path: `${OUT}/final-mid.png` });

// shop
await page.evaluate(() => {
  const g = window.game;
  g.spores = 30; g.updateHUD();
  const f = g.level.forges[0];
  g.player.x = f.x - g.player.w / 2;
  g.player.y = f.y - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(250);
await page.keyboard.press('e');
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/final-shop.png` });
const buy = await page.$('[data-buy="1"]:not([disabled])');
if (buy) await buy.click();
await page.waitForTimeout(450);
await page.screenshot({ path: `${OUT}/final-shop-bought.png` });
await page.click('#shopClose');
await page.waitForTimeout(400);
const noticeAfterClose = await page.evaluate(() => {
  const n = document.querySelector('#shopNotice');
  return n ? { text: n.textContent, visible: getComputedStyle(n).display !== 'none' && n.classList.contains('show') } : null;
});

// boss 1
await teleport(page, 95);
await page.waitForTimeout(2300);
await page.screenshot({ path: `${OUT}/final-boss1.png` });

// pause overlay
await page.keyboard.press('Escape');
await page.waitForTimeout(350);
await page.screenshot({ path: `${OUT}/final-pause.png` });
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// quit to title -> level card must be gone
await page.click('#menuBtn').catch(() => page.click('#quitBtn'));
await page.waitForTimeout(700);
const titleState = await page.evaluate(() => {
  const card = document.querySelector('#levelCard');
  return {
    state: window.game.state,
    cardHidden: card.classList.contains('hidden'),
    cardShown: card.classList.contains('show'),
    cardText: card.textContent.trim().replace(/\s+/g, ' '),
  };
});
await page.screenshot({ path: `${OUT}/final-title-return.png` });

// boss 2
await page.evaluate(() => {
  const g = window.game;
  g.loadLevel(1);
  g.player.x = 22 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(500);
await page.evaluate(() => {
  const g = window.game;
  g.player.x = 95 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(2300);
await page.screenshot({ path: `${OUT}/final-boss2.png` });

// boss 3
await page.evaluate(() => {
  const g = window.game;
  g.loadLevel(2);
  g.player.x = 22 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(500);
await page.evaluate(() => {
  const g = window.game;
  g.player.x = 95 * 48;
  g.player.y = g.level.arenaData.groundY - g.player.h;
  g.snapCamera();
});
await page.waitForTimeout(2300);
await page.screenshot({ path: `${OUT}/final-boss3.png` });

// victory
await page.evaluate(() => { window.game.winGame(); });
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/final-victory.png` });
const victoryText = await page.evaluate(() => document.querySelector('#victoryStats').innerText.replace(/\s+/g, ' '));

console.log(JSON.stringify({ noticeAfterClose, titleState, victoryText, errors }, null, 2));
await page.context().close();

// ---------- Mobile 390x844 ----------
const mob = await newPage({ width: 390, height: 844 }, true);
await mob.screenshot({ path: `${OUT}/final-m-title.png` });
await mob.click('#playBtn');
await mob.waitForTimeout(3400);
await mob.screenshot({ path: `${OUT}/final-m-play.png` });
await mob.evaluate(() => {
  const g = window.game;
  g.spores = 30; g.updateHUD();
  const f = g.level.forges[0];
  g.player.x = f.x - g.player.w / 2;
  g.player.y = f.y - g.player.h;
  g.snapCamera();
});
await mob.waitForTimeout(250);
await mob.keyboard.press('e');
await mob.waitForTimeout(500);
await mob.screenshot({ path: `${OUT}/final-m-shop.png` });

// ---------- Small mobile 320x568 shop scroll ----------
const small = await newPage({ width: 320, height: 568 }, true);
await small.click('#playBtn');
await small.waitForTimeout(2800);
await small.evaluate(() => {
  const g = window.game;
  g.spores = 10; g.updateHUD();
  const f = g.level.forges[0];
  g.player.x = f.x - g.player.w / 2;
  g.player.y = f.y - g.player.h;
  g.snapCamera();
});
await small.waitForTimeout(250);
await small.keyboard.press('e');
await small.waitForTimeout(500);
await small.screenshot({ path: `${OUT}/final-small-shop-top.png` });
const scrollInfo = await small.evaluate(() => {
  const p = document.querySelector('.shop-panel');
  const before = p.scrollTop;
  p.scrollTop = 400;
  return { before, after: p.scrollTop, scrollable: p.scrollHeight > p.clientHeight, touchAction: getComputedStyle(p).touchAction, sh: p.scrollHeight, ch: p.clientHeight };
});
await small.waitForTimeout(300);
await small.screenshot({ path: `${OUT}/final-small-shop-bottom.png` });
console.log(JSON.stringify({ scrollInfo, errors2: errors }, null, 2));

await browser.close();

