import { createRequire } from 'module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const errors = [];
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const page = await context.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);

await page.tap('#playBtn');
await page.waitForTimeout(2500);
const before = await page.evaluate(() => ({ x: window.game.player.x, y: window.game.player.y, state: window.game.state }));

// Hold right touch button for 900ms
const right = await page.$('[data-control="right"]') || await page.$('#touchRight') || await page.$('.touch-right');
const jump = await page.$('[data-control="jump"]') || await page.$('#touchJump') || await page.$('.touch-jump');
const ids = await page.evaluate(() => Array.from(document.querySelectorAll('[data-control], .touch-btn, .touch-control')).map(el => ({ id: el.id, cls: el.className, c: el.dataset.control })));
console.log('controls', JSON.stringify(ids));
if (right) {
  const box = await right.boundingBox();
  await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2).catch(() => {});
}
// Simulate pointer press-hold via dispatch on the right control
if (right) {
  await right.dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true, bubbles: true });
  await page.waitForTimeout(900);
  await right.dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true, bubbles: true });
}
const afterMove = await page.evaluate(() => ({ x: window.game.player.x, y: window.game.player.y, vx: window.game.player.vx }));
if (jump) {
  await jump.dispatchEvent('pointerdown', { pointerId: 2, pointerType: 'touch', isPrimary: true, bubbles: true });
  await page.waitForTimeout(300);
  const midJump = await page.evaluate(() => ({ y: window.game.player.y, vy: window.game.player.vy, grounded: window.game.player.grounded }));
  await jump.dispatchEvent('pointerup', { pointerId: 2, pointerType: 'touch', isPrimary: true, bubbles: true });
  console.log('jump', JSON.stringify(midJump));
}

// Continue flow: save exists? buy nothing, just check title continue button after quit
await page.evaluate(() => { window.game.spores = 12; window.game.armor = 1; window.game.saveProgress(); window.game.quitToTitle(); });
await page.waitForTimeout(500);
const continueState = await page.evaluate(() => {
  const b = document.querySelector('#continueBtn');
  return { exists: !!b, hidden: b ? b.classList.contains('hidden') : null, text: b ? b.textContent.trim() : null, title: !document.querySelector('#title').classList.contains('hidden') };
});
await page.screenshot({ path: '/tmp/opencode/shots/final-m-title-continue.png' });
if (continueState.exists && !continueState.hidden) {
  await page.tap('#continueBtn');
  await page.waitForTimeout(2200);
}
const resumed = await page.evaluate(() => ({ state: window.game.state, armor: window.game.armor, spores: window.game.spores, level: window.game.levelIndex, hudHidden: document.querySelector('#hud').classList.contains('hidden'), titleHidden: document.querySelector('#title').classList.contains('hidden') }));

// pause -> title
await page.evaluate(() => window.game.pauseGame());
await page.waitForTimeout(300);
const pauseVisible = await page.evaluate(() => !document.querySelector('#pause').classList.contains('hidden'));
await page.tap('#quitBtn');
await page.waitForTimeout(700);
const backToTitle = await page.evaluate(() => ({ state: window.game.state, titleVisible: !document.querySelector('#title').classList.contains('hidden'), cardHidden: document.querySelector('#levelCard').classList.contains('hidden') }));

console.log(JSON.stringify({ before, afterMove, continueState, resumed, pauseVisible, backToTitle, errors }, null, 2));
await browser.close();

