const browser = await chromium.launch({ args: ['--no-sandbox'] });
const errors = [];
for (const [w, h, mobile] of [[768, 1024, true], [1024, 768, false], [820, 1180, true], [932, 430, true]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, isMobile: mobile, hasTouch: mobile, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errors.push(`${w}x${h} pageerror: ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`${w}x${h} console: ${m.text()}`); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/opencode/shots/dev-${w}x${h}-title.png` });
  const fit = await page.evaluate(() => {
    const r = (s) => { const el = document.querySelector(s); if (!el) return null; const b = el.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), right: Math.round(b.right), bottom: Math.round(b.bottom) }; };
    return { vw: innerWidth, vh: innerHeight, title: r('#title'), play: r('#playBtn'), controls: r('.hint-row'), touch: r('#touch') };
  });
  await page.tap('#playBtn');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: `/tmp/opencode/shots/dev-${w}x${h}-play.png` });
  const touchBoxes = await page.evaluate(() => Array.from(document.querySelectorAll('#touch .touch-btn')).map((el) => { const b = el.getBoundingClientRect(); return { a: el.dataset.action, x: Math.round(b.x), y: Math.round(b.y), r: Math.round(b.right), b: Math.round(b.bottom) }; }));
  const off = touchBoxes.filter((t) => t.x < 0 || t.y < 0 || t.r > innerWidth || t.b > innerHeight);
  console.log(JSON.stringify({ size: `${w}x${h}`, fit, offscreenTouch: off, errors }));
  await ctx.close();
}
console.log('ALL ERRORS', errors);
await browser.close();

